import inspect

def list_si_functions():
    """
    List all available functions in matplotlab.si module
    """
    functions_db = {
        "PSO Algorithms": {
            "pso_basic": "Basic PSO - simple optimization (Lab 3)",
            "pso_adaptive": "Adaptive PSO - adaptive inertia + velocity clamping (Lab 4)",
            "PSO": "Modular PSO class - advanced with boundary control (Lab 6)",
        },
        "Meta-heuristics": {
            "run_aco": "Ant Colony Optimization - Traveling Salesman Problem solver (Lab 7)",
        },
        "Search Methods": {
            "random_search": "Random Search - stochastic sampling",
            "brute_force": "Brute Force Search - grid-based deterministic search",
        },
        "Fitness Functions": {
            "sphere": "Sphere function - f(x) = Sum(x^2)",
            "rastrigin": "Rastrigin function - multimodal f(x) = 10n + Sum(x^2 - 10cos(2*pi*x))",
            "quadratic": "Quadratic function - f(x) = (x-3)^2",
            "oscillating": "Oscillating function - f(x) = x^2 + 10(1 - cos(2*pi*x))",
            "multi_modal": "Multi-modal function - f(x) = x^4 - 3x^3 + 2",
            "lab6_custom": "Lab 6 custom - f(x) = 10n + Sum((x-2)^2 - 10cos(2*pi*(x-2)))",
        },
        "Boundary Handling": {
            "boundary_clamping": "Clamp positions to bounds",
            "boundary_reflecting": "Reflect particles off boundaries, reverse velocity",
            "boundary_wraparound": "Wrap positions to opposite boundary",
            "boundary_random_reset": "Randomly reset out-of-bounds positions",
            "boundary_velocity_damping": "Reverse velocity with damping on boundary crossing",
        },
    }
    
    print("=" * 80)
    print("MATPLOTLAB SI MODULE - COMPLETE FUNCTION LISTING")
    print("=" * 80)
    
    total_count = 0
    for category, functions in functions_db.items():
        print(f"\n{category}: ({len(functions)} functions)")
        print("-" * 80)
        for func_name, description in functions.items():
            print(f"  {func_name:30} | {description}")
            total_count += 1
    
    print("\n" + "=" * 80)
    print(f"TOTAL FUNCTIONS: {total_count}")
    print("=" * 80)
    
    return functions_db


def show_all_params():
    """
    Show parameters for ALL functions in the module
    Usage: from matplotlab.si import show_all_params; show_all_params()
    """
    import sys
    
    parent = sys.modules['matplotlab.si']
    
    pso_and_meta = []
    search_methods = []
    fitness_funcs = []
    boundary_handlers = []
    
    for name in dir(parent):
        if not name.startswith('_'):
            obj = getattr(parent, name)
            if hasattr(obj, 'params'):
                if name in ['pso_basic', 'pso_adaptive', 'run_aco']:
                    pso_and_meta.append(obj)
                elif name in ['random_search', 'brute_force']:
                    search_methods.append(obj)
                elif name in ['sphere', 'rastrigin', 'quadratic', 'oscillating', 'multi_modal', 'lab6_custom']:
                    fitness_funcs.append(obj)
                elif 'boundary' in name:
                    boundary_handlers.append(obj)
    
    print("\n" + "=" * 80)
    print("FUNCTION PARAMETERS QUICK REFERENCE")
    print("=" * 80)
    
    categories = [
        ("PSO & Meta-heuristics", pso_and_meta),
        ("Search Methods", search_methods),
        ("Fitness Functions", fitness_funcs),
        ("Boundary Handling", boundary_handlers)
    ]
    
    for category, func_list in categories:
        if func_list:
            print(f"\n{category}:")
            print("-" * 80)
            for func in sorted(func_list, key=lambda f: f.__name__):
                sig = inspect.signature(func.func)
                print(f"  {func.__name__}{sig}")
    
    print("\n" + "=" * 80)
    print("HOW TO GET HELP:")
    print("  func.help()     - Show full documentation and parameters")
    print("  func.params()   - Show just function signature")
    print("  func.show()     - Show complete source code")
    print("  help(func)      - Python's built-in help")
    print("=" * 80 + "\n")
